use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\Schema;
use Illuminate\Support\Facades\DB;

Schema::create('records', function ($table) {
    $table->id();
    $table->string('name')->default('old');
    $table->string('code')->nullable();
    $table->integer('version')->default(1);
    $table->text('data')->nullable();
    $table->timestamps();
});

class Record extends Model
{
    protected $table = 'records';
    protected $guarded = [];
}

$record = Record::create(['name' => 'old', 'code' => 'A']);
$record->update(['name' => 'z']);
Record::create(['name' => 'a']);
$allowed = ['name' => 'name', 'created_at' => 'created_at'];
$requested = 'name';
$query = DB::table('records')->orderBy($allowed[$requested]);
echo $query->pluck('name')->implode(',').':';
$bound = DB::table('records')->orderByRaw('? ASC', ['name']);
echo $bound->getBindings() === ['name'] && str_contains($bound->toSql(), '? ASC') ? 'bound-value' : 'other';
